  color: var(--muted);
}

.text-field__input {
  font: inherit;
  font-size: clamp(0.9rem, 0.85rem + 0.25vw, 1.05rem);
  color: var(--ink);
  background: var(--slide);
  padding: 0.6em 0.8em;
  border: 1px solid var(--muted);
  border-radius: 0.5rem;
}

.text-field__input::placeholder {
  color: var(--muted);
  opacity: 1;
}

.text-field__input:focus {
  border-color: var(--myelin);
}

.text-field__input[aria-invalid="true"] {
  border-color: var(--cresyl);
  box-shadow: inset 0 0 0 1px var(--cresyl);
}

.text-field__error {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin: 0;
  font-size: clamp(0.8rem, 0.75rem + 0.2vw, 0.95rem);
  font-weight: 600;
  color: var(--ink);
}

.text-field__mark {
  flex: none;
  width: 0.6rem;
  height: 0.6rem;
  border-radius: 999px;
  background: var(--cresyl);
}

/* Transitions run only when motion is allowed. */
:root:not([data-motion="reduce"]) .text-field__input {
  transition: border-color 150ms ease;
}

@media (prefers-reduced-motion: reduce) {
  .text-field__input {
    transition: none;
  }
}
